//! Shared integration-test plumbing.
//!
//! Mostly snapshot machinery; [`files`] is the one piece the non-snapshot
//! tests want too, so a test binary using only part of this module is normal
//! and declares it `#[allow(dead_code)]`.
//!
//! Follows the pattern `std.wscripti` already uses in this workspace: the
//! expected output is a committed file, regenerated by an environment
//! variable, and a test fails when the committed copy is stale. Reviewing a
//! change is `just snap-regen` followed by reading `git diff` — no snapshot
//! tool to install, and no third-party dev-dependency (this workspace has
//! none).

use std::path::{Path, PathBuf};

/// Set by `just snap-regen` to rewrite snapshots instead of asserting.
pub fn regenerating() -> bool {
    std::env::var_os("WSCRIPT_REGEN_SNAP").is_some()
}

/// Every file under `root` with extension `ext`, depth-first, sorted so the
/// order is stable across filesystems.
pub fn files(root: &Path, ext: &str) -> Vec<PathBuf> {
    let mut out = Vec::new();
    collect(root, ext, &mut out);
    out.sort();
    out
}

fn collect(dir: &Path, ext: &str, out: &mut Vec<PathBuf>) {
    let Ok(entries) = std::fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        if path.is_dir() {
            collect(&path, ext, out);
        } else if path.extension().is_some_and(|e| e == ext) {
            out.push(path);
        }
    }
}

/// 1-based line and column of a byte offset. Columns count characters, not
/// bytes, so a multi-byte character advances the column by one.
pub fn line_col(src: &str, offset: u32) -> (usize, usize) {
    let offset = (offset as usize).min(src.len());
    let mut line = 1;
    let mut col = 1;
    for (i, ch) in src.char_indices() {
        if i >= offset {
            break;
        }
        if ch == '\n' {
            line += 1;
            col = 1;
        } else {
            col += 1;
        }
    }
    (line, col)
}

/// `1:20-1:27`, or `1:20` when the span is empty.
pub fn span_str(src: &str, lo: u32, hi: u32) -> String {
    let (l1, c1) = line_col(src, lo);
    if lo == hi {
        return format!("{l1}:{c1}");
    }
    let (l2, c2) = line_col(src, hi);
    format!("{l1}:{c1}-{l2}:{c2}")
}

/// Compare `actual` against the fixture's committed snapshot, or rewrite it
/// when regenerating. Returns an explanation on mismatch rather than
/// panicking, so a runner can report every stale fixture in one go.
pub fn check_snapshot(fixture: &Path, actual: &str) -> Result<(), String> {
    let snap = fixture.with_extension("snap");
    if regenerating() {
        std::fs::write(&snap, actual).unwrap_or_else(|e| panic!("writing {}: {e}", snap.display()));
        return Ok(());
    }
    let expected = std::fs::read_to_string(&snap).unwrap_or_default();
    if expected == actual {
        return Ok(());
    }
    Err(format!(
        "{}\n--- expected ---\n{expected}--- actual ---\n{actual}",
        snap.display()
    ))
}

/// Fail once, listing every stale fixture, with the regen command.
pub fn report(failures: Vec<String>) {
    if failures.is_empty() {
        return;
    }
    panic!(
        "{} snapshot(s) out of date:\n\n{}\n\
         Re-run with `just snap-regen` and review the diff.",
        failures.len(),
        failures.join("\n")
    );
}
